# ============================================================
# Note
# This script performs cell-type-specific regional differential
# expression analysis.
#
# The input h5ad files were generated by splitting the integrated
# whole-brain dataset, integrated_whole_brain.h5ad, according to
# the edited Jorstad-defined cell-type labels. Each h5ad file
# therefore contains cells from one specific cell type.
#

import os
import glob
import re
import pandas as pd
import numpy as np
import scanpy as sc
import scipy.sparse
import memento
from statsmodels.stats.multitest import multipletests
# Path Definitions
materials_PATH='/mnt/disk1/docker_mount_file/materials/'

INPUT_DIR = f"{materials_PATH}integrated_whole_brain_celltype_V4_0_h5ad/"
OUTPUT_DIR = "/mnt/leiwk/neuro_work/V4_0_code/results/DEG/celltype_region/"
DATA_EDITION = "integrated_data_V4_0"

NUM_BOOT = 5000
NUM_CPUS = 48
CAPTURE_RATE = 0.25
MIN_PERC_GROUP = 0.7
COVARIATES = ['batch_harmony_index']
FILE_START_INDEX = 20
os.makedirs(OUTPUT_DIR, exist_ok=True)

def perform_one_vs_all(target_roi, adata, covariates, capture_rate=0.25, gene_list=None, num_boot=5000, num_cpus=48,
                       min_perc_group=0.7):
    adata.obs['treatment_binary'] = (adata.obs['roi'] == target_roi).astype(int)
    memento.setup_memento(adata, q_column='capture_rate')
    group_columns = ['treatment_binary'] + covariates
    memento.create_groups(adata, label_columns=group_columns)
    memento.compute_1d_moments(adata, min_perc_group=min_perc_group, gene_list=gene_list)
    sample_meta = memento.get_groups(adata)
    cov_df = sample_meta[covariates]
    treat_df = sample_meta[['treatment_binary']]
    memento.ht_1d_moments(adata, treatment=treat_df, covariate=cov_df, num_boot=num_boot, verbose=1, num_cpus=num_cpus)
    result_1d = memento.get_1d_ht_result(adata).copy()
    result_1d['roi'] = target_roi
    treatment_cells = adata.obs['treatment_binary'] == 1
    control_cells = adata.obs['treatment_binary'] == 0
    if gene_list is None:
        gene_list = adata.var.index.tolist()
    gene_expression = adata[:, gene_list].X > 0
    if scipy.sparse.issparse(gene_expression):
        gene_expression = gene_expression.toarray()
    gene_expression_df = pd.DataFrame(gene_expression, index=adata.obs_names, columns=gene_list)
    pct_1 = gene_expression_df.loc[treatment_cells].mean() * 100
    pct_2 = gene_expression_df.loc[control_cells].mean() * 100
    result_1d['pct.1'] = result_1d['gene'].map(pct_1)
    result_1d['pct.2'] = result_1d['gene'].map(pct_2)
    return result_1d

def preprocess_adata(adata):
    adata.obs['capture_rate'] = CAPTURE_RATE
    if 'batch_harmony' in adata.obs.columns:
        adata.obs['batch_harmony_index'] = adata.obs['batch_harmony'].map({
            'Siletti_whole_brain': 0,
            'Jorstad_et_al': 1
        }).astype('category')
    return adata


all_files = glob.glob(os.path.join(INPUT_DIR, "*.h5ad"))
target_files = all_files[FILE_START_INDEX:]
print(
    f"Total files found: {len(all_files)}. Processing {len(target_files)} files (starting from index {FILE_START_INDEX}).")
for file_path in target_files:
    file_name = os.path.basename(file_path)
    match = re.search(r'integrated_whole_counts_V4_0_(.+)\.h5ad', file_name)
    if not match:
        print(f"[Warn] Filename format mismatch, skipping: {file_name}")
        continue
    celltype = match.group(1)
    print(f"\n{'=' * 20}\nProcessing Cell Type: {celltype}\n{'=' * 20}")


    try:
        celltype_h5ad = sc.read(file_path)
        celltype_h5ad = preprocess_adata(celltype_h5ad)
    except Exception as e:
        print(f"[Error] Failed to read file {file_path}: {e}")
        continue
    unique_rois = celltype_h5ad.obs['roi'].unique().tolist()
    de_results = {}
    print(f" -> Found {len(unique_rois)} ROIs in this cell type.")
    for roi in unique_rois:
        print(f"    -> Analyzing ROI: {roi} vs Others")
        try:
            result = perform_one_vs_all(
                target_roi=roi,
                adata=celltype_h5ad,
                covariates=COVARIATES,
                capture_rate=CAPTURE_RATE,
                gene_list=None,
                num_boot=NUM_BOOT,
                num_cpus=NUM_CPUS,
                min_perc_group=MIN_PERC_GROUP
            )
            de_results[roi] = result
        except Exception as e:
            print(f"    [Error] Failed to analyze ROI {roi}: {e}")

    if de_results:
        combined_results = []
        for roi, df in de_results.items():
            df = df.copy()
            df['roi'] = roi
            combined_results.append(df)
        all_de_results = pd.concat(combined_results, ignore_index=True)
        all_de_results['de_padj'] = all_de_results.groupby('roi')['de_pval'].transform(
            lambda x: multipletests(x, method='fdr_bh')[1])
        all_de_results['dv_padj'] = all_de_results.groupby('roi')['dv_pval'].transform(
            lambda x: multipletests(x, method='fdr_bh')[1])
        all_de_results['celltype'] = celltype
        # Save to CSV
        output_filename = os.path.join(OUTPUT_DIR, f"{DATA_EDITION}_{celltype}_region_specific_DE_genes.csv")
        all_de_results.to_csv(output_filename, index=False)
        print(f" -> File saved: {output_filename}")
    else:
        print(f" -> No valid results generated for {celltype}, skipping save.")